#define MAXN 1000

int H, W;
int grid[MAXN][MAXN];
int parent[MAXN * MAXN];
int rank[MAXN * MAXN];
int isRidge[MAXN * MAXN];

int dx[4] = {-1, 1, 0, 0};
int dy[4] = {0, 0, -1, 1};

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

void union_sets(int a, int b) {
    int ra = find(a), rb = find(b);
    if (ra == rb) return;
    if (rank[ra] < rank[rb])
        parent[ra] = rb;
    else if (rank[ra] > rank[rb])
        parent[rb] = ra;
    else {
        parent[rb] = ra;
        rank[ra]++;
    }
}

typedef struct {
    int val, idx;
} Cell;

int cmp(const void *a, const void *b) {
    return ((Cell*)b)->val - ((Cell*)a)->val;
}

int main() {
    scanf("%d %d", &H, &W);
    Cell cells[H * W];
    int total = H * W;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            scanf("%d", &grid[i][j]);
            int idx = i * W + j;
            cells[idx] = (Cell){grid[i][j], idx};
            parent[idx] = idx;
            rank[idx] = 0;
            isRidge[idx] = 0;
        }
    }
    qsort(cells, total, sizeof(Cell), cmp);

    int visited[H][W];
    for (int i = 0; i < H; i++)
        for (int j = 0; j < W; j++)
            visited[i][j] = 0;

    for (int c = 0; c < total; c++) {
        int idx = cells[c].idx;
        int x = idx / W;
        int y = idx % W;
        visited[x][y] = 1;

        int root = -1;
        int multiple = 0;
