typedef struct {
    int h;
    int idx;
} Node;

static int cmp_node(const void *a, const void *b) {
    const Node *x = (const Node *)a;
    const Node *y = (const Node *)b;
    if (x->h < y->h) return -1;
    if (x->h > y->h) return 1;
    return 0;
}

int main(void) {
    int H, W;
    if (scanf("%d %d", &H, &W) != 2) return 0;

    int N = H * W;
    int *M = (int *)malloc(sizeof(int) * N);
    Node *ord = (Node *)malloc(sizeof(Node) * N);
    unsigned char *ridge = (unsigned char *)calloc(N, sizeof(unsigned char));
    int *sink1 = (int *)malloc(sizeof(int) * N);
    int *sink2 = (int *)malloc(sizeof(int) * N);

    for (int i = 0; i < N; i++) {
        scanf("%d", &M[i]);
        ord[i].h = M[i];
        ord[i].idx = i;
    }

    qsort(ord, N, sizeof(Node), cmp_node);

    for (int t = 0; t < N; t++) {
        int v = ord[t].idx;
        int r = v / W, c = v % W;

        int ncnt = 0;
        int nb[4];

        if (r > 0) {
            int u = v - W;
            if (M[u] < M[v]) nb[ncnt++] = u;
        }
        if (r + 1 < H) {
            int u = v + W;
            if (M[u] < M[v]) nb[ncnt++] = u;
        }
        if (c > 0) {
            int u = v - 1;
            if (M[u] < M[v]) nb[ncnt++] = u;
        }
        if (c + 1 < W) {
            int u = v + 1;
            if (M[u] < M[v]) nb[ncnt++] = u;
        }

        if (ncnt == 0) {
            sink1[v] = v;
            sink2[v] = -1;
            continue;
        }

        int a = -1, b = -1;
        for (int i = 0; i < ncnt; i++) {
            int u = nb[i];
            int x1 = sink1[u], x2 = sink2[u];

            if (a == -1) a = x1;
            else if (a != x1 && b == -1) b = x1;

            if (x2 != -1) {
                if (a == -1) a = x2;
                else if (a != x2 && b == -1) b = x2;
            }

            if (b != -1) break;
        }

        if (b != -1) {
            ridge[v] = 1;
            sink1[v] = a;
            sink2[v] = b;
        } else {
            sink1[v] = a;
            sink2[v] = -1;
        }
    }

    int ans = 0;
    for (int i = 0; i < N; i++) ans += ridge[i];

    printf("%d\n", ans);

    free(M);
    free(ord);
    free(ridge);
    free(sink1);
    free(sink2);
    return 0;
}

