    static int H, W;
    static int[][] height;
    static int[][] component; // component id for each cell
    static int compCount;
    static int[] dx = {-1, 1, 0, 0};
    static int[] dy = {0, 0, -1, 1};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        H = Integer.parseInt(st.nextToken());
        W = Integer.parseInt(st.nextToken());
        height = new int[H][W];
        component = new int[H][W];

        // Store cells with their heights for sorting
        int[][] cells = new int[H*W][3];
        int idx = 0;
        for (int i = 0; i < H; i++) {
            st = new StringTokenizer(br.readLine());
            for (int j = 0; j < W; j++) {
                height[i][j] = Integer.parseInt(st.nextToken());
                cells[idx][0] = height[i][j];
                cells[idx][1] = i;
                cells[idx][2] = j;
                component[i][j] = -1;
            }
        }

        // Sort cells by height descending
        Arrays.sort(cells, (a, b) -> b[0] - a[0]);

        // DSU for tracking connected components of processed cells
        int[] parent = new int[H*W];
        int[] size = new int[H*W];
        boolean[] active = new boolean[H*W];
        int[] compSize = new int[H*W]; // number of cells in each DSU component

        for (int i = 0; i < H*W; i++) {
            parent[i] = i;
            size[i] = 1;
        }

        int ridgeCount = 0;
        int cellIdx = 0;

        while (cellIdx < H*W) {
            int curHeight = cells[cellIdx][0];
            // Process all cells with the same height
            List<Integer> sameHeightCells = new ArrayList<>();
            while (cellIdx < H*W && cells[cellIdx][0] == curHeight) {
                int x = cells[cellIdx][1];
                int y = cells[cellIdx][2];
                int id = x * W + y;
                active[id] = true;
                sameHeightCells.add(id);

                // Union with already active neighbors
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d];
                    int ny = y + dy[d];
                    if (nx >= 0 && nx < H && ny >= 0 && ny < W) {
                        int nid = nx * W + ny;
                        if (active[nid]) {
                            union(parent, size, id, nid);
                        }
                    }
                }
                cellIdx++;
            }

            // Now for each cell in sameHeightCells, check how many distinct
            // components its lower neighbors belong to
            for (int id : sameHeightCells) {
                int x = id / W;
                int y = id % W;
                Set<Integer> compSet = new HashSet<>();
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d];
                    int ny = y + dy[d];
                    if (nx >= 0 && nx < H && ny >= 0 && ny < W) {
                        if (height[nx][ny] < height[x][y]) {
                            int nid = nx * W + ny;
                            // The neighbor must have been processed (active)
                            // and belongs to some component
                            int root = find(parent, nid);
                            compSet.add(root);
                        }
                    }
                }
                if (compSet.size() >= 2) {
                    ridgeCount++;
                }
            }
        }

        System.out.println(ridgeCount);
    }

    static int find(int[] parent, int x) {
        if (parent[x] != x) {
            parent[x] = find(parent, parent[x]);
        }
        return parent[x];
    }

    static void union(int[] parent, int[] size, int a, int b) {
        int ra = find(parent, a);
        int rb = find(parent, b);
        if (ra != rb) {
            if (size[ra] < size[rb]) {
                parent[ra] = rb;
                size[rb] += size[ra];
            } else {
                parent[rb] = ra;
                size[ra] += size[rb];
            }
        }
    }
}

