            for (int j = 0; j < W; j++) {
                elev[i][j] = Integer.parseInt(st.nextToken());
            }
        }

        Integer[] order = new Integer[H * W];
        for (int i = 0; i < H * W; i++) order[i] = i;
        Arrays.sort(order, (a, b) -> elev[a/W][a%W] - elev[b/W][b%W]);

        parent = new int[H * W];
        for (int i = 0; i < H * W; i++) parent[i] = i;

        int[] dx = {0, 0, 1, -1};
        int[] dy = {1, -1, 0, 0};
        int ridgeCount = 0;

        for (int idx : order) {
            int r = idx / W, c = idx % W;
            Set<Integer> roots = new HashSet<>();
            for (int d = 0; d < 4; d++) {
                int nr = r + dx[d], nc = c + dy[d];
                if (nr >= 0 && nr < H && nc >= 0 && nc < W && elev[nr][nc] < elev[r][c]) {
                    roots.add(find(nr * W + nc));
                }
            }
            if (roots.size() > 1) ridgeCount++;
            for (int root : roots) union(root, idx);
        }

        System.out.println(ridgeCount);
    }
}

