public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int H = fs.nextInt();
        int W = fs.nextInt();
        int N = H * W;

        int[] height = new int[N];
        int[] order = new int[N];
        for (int i = 0; i < N; i++) order[i] = i;

        for (int r = 0; r < H; r++) {
            for (int c = 0; c < W; c++) {
                int id = r * W + c;
                height[id] = fs.nextInt();
            }
        }

        // Sort cells by height ascending.
        Integer[] ordObj = new Integer[N];
        for (int i = 0; i < N; i++) ordObj[i] = i;
        Arrays.sort(ordObj, Comparator.comparingInt(a -> height[a]));

        int[] dp = new int[N];
        // dp[v]:
        // 0 = not ridge (reaches exactly one sink)
        // 1 = ridge (reaches multiple sinks)

        for (int idx = 0; idx < N; idx++) {
            int v = ordObj[idx];
            int r = v / W;
            int c = v % W;

            int lowerCount = 0;
            boolean ridge = false;

            // up
            if (r > 0) {
                int u = v - W;
                if (height[u] < height[v]) {
                    lowerCount++;
                    if (dp[u] == 1) ridge = true;
                }
            }
            // down
            if (r + 1 < H) {
                int u = v + W;
                if (height[u] < height[v]) {
                    lowerCount++;
                    if (dp[u] == 1) ridge = true;
                }
            }
            // left
            if (c > 0) {
                int u = v - 1;
                if (height[u] < height[v]) {
                    lowerCount++;
                    if (dp[u] == 1) ridge = true;
                }
            }
            // right
            if (c + 1 < W) {
                int u = v + 1;
                if (height[u] < height[v]) {
                    lowerCount++;
                    if (dp[u] == 1) ridge = true;
                }
            }

            if (lowerCount == 0) {
                dp[v] = 0; // sink itself
            } else if (ridge || lowerCount >= 2) {
                dp[v] = 1;
            } else {
                dp[v] = 0;
            }
        }

        long ans = 0;
        for (int i = 0; i < N; i++) ans += dp[i];
        System.out.println(ans);
    }
}

