                    size[a] += size[b];
                    sinkCount[a] += sinkCount[b];
                }
            }
        }

        // Now check if the component has multiple sinks
        int comp = find(idx);
        if (sinkCount[comp] >= 2) {
            // Check if this cell is the highest in the component that causes multiple sinks
            // Actually, any cell that when added makes its component have >=2 sinks is a ridge.
            // But we need to be careful: the cell itself might be the only sink if it's a sink cell and component size 1.
            // Since we process descending, the first time a component gets >=2 sinks, the cell that caused it is a ridge.
            // However, multiple cells might be ridges in the same component? Let's think.
            // If we add a cell and the component already had 2 sinks, then this cell is not necessarily a ridge because the multiple sinks existed before.
            // So we need to check if before adding this cell, the component had <2 sinks, and after adding it has >=2.
            // But we already merged, so we need to track previous sink count.
        }
    }

    // The above logic is still messy. Let's implement a clean solution using DSU with offline processing.

    // Reset everything
    fill(parent.begin(), parent.end(), 0);
    iota(parent.begin(), parent.end(), 0);
    fill(size.begin(), size.end(), 1);
    fill(sinkCount.begin(), sinkCount.end(), 0);
    fill(isSink.begin(), isSink.end(), false);
    fill(active.begin(), active.end(), vector<bool>(W, false));

    ridgeCount = 0;

    // We'll process cells from highest to lowest.
    // For each cell, we first determine if it's a sink (no lower active neighbors).
    // Then we temporarily set its sink status.
    // Then we merge with neighbors.
    // After merging, we check if the component now has >=2 sinks.
    // To avoid counting the same ridge multiple times, we can mark components that have already been counted.

    vector<bool> counted(H * W, false);

    for (auto &cell : cells) {
        int elev = cell.first;
        int i = cell.second.first;
        int j = cell.second.second;
        int idx = i * W + j;

        active[i][j] = true;

        // Determine if this cell is a sink
        bool isSinkCell = true;
        for (int d = 0; d < 4; d++) {
            int ni = i + dx[d];
            int nj = j + dy[d];
            if (ni >= 0 && ni < H && nj >= 0 && nj < W && active[ni][nj]) {
                isSinkCell = false;
                break;
            }
        }

        // Set initial sink status for this cell
        if (isSinkCell) {
            isSink[idx] = true;
            sinkCount[find(idx)] = 1;
        } else {
            isSink[idx] = false;
            sinkCount[find(idx)] = 0;
        }

        // Merge with active lower neighbors
        for (int d = 0; d < 4; d++) {
            int ni = i + dx[d];
            int nj = j + dy[d];
            if (ni >= 0 && ni < H && nj >= 0 && nj < W && active[ni][nj]) {
                int nidx = ni * W + nj;
                int a = find(idx);
                int b = find(nidx);
                if (a != b) {
                    // Save sink counts before merge
                    int sinksA = sinkCount[a];
                    int sinksB = sinkCount[b];
                    bool countedA = counted[a];
                    bool countedB = counted[b];

                    if (size[a] < size[b]) {
                        swap(a, b);
                        swap(sinksA, sinksB);
                        swap(countedA, countedB);
                    }
                    parent[b] = a;
                    size[a] += size[b];
                    sinkCount[a] = sinksA + sinksB;
                    counted[a] = countedA || countedB;
                }
            }
        }

        int comp = find(idx);
        if (sinkCount[comp] >= 2 && !counted[comp]) {
            counted[comp] = true;
            ridgeCount++;
        }
    }

    cout << ridgeCount << "\n";

    return 0;
}

