#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    int N = H * W;

    vector<int> h(N);
    for (int i = 0; i < H; ++i) {
        for (int j = 0; j < W; ++j) {
            cin >> h[i * W + j];
        }
    }

    vector<int> order(N);
    iota(order.begin(), order.end(), 0);
    sort(order.begin(), order.end(), [&](int a, int b) {
        return h[a] < h[b];
    });

    // dp[v]:
    // 0 = exactly one sink reachable
    // 1 = multiple sinks reachable
    vector<unsigned char> multi(N, 0);

    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    for (int idx = 0; idx < N; ++idx) {
        int v = order[idx];
        int r = v / W, c = v % W;

        int firstLower = -1;
        bool isMulti = false;

        for (int k = 0; k < 4; ++k) {
            int nr = r + dr[k], nc = c + dc[k];
            if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
            int to = nr * W + nc;
            if (h[to] < h[v]) {
                if (firstLower == -1) firstLower = to;
                if (multi[to]) isMulti = true;
            }
        }

        if (firstLower == -1) {
            // sink
            multi[v] = 0;
            continue;
        }

        if (!isMulti) {
            // All reachable sinks are unions of sinks of lower neighbors.
            // Since heights are unique and each lower neighbor with multi=0 has exactly one sink,
            // v is non-ridge iff all lower neighbors lead to the same sink.
            int sinkRep = -1;
            bool different = false;

            // We need representative sink for each lower neighbor.
            // Compress by following a unique lower path only while node is non-multi and non-sink.
            auto getSink = [&](int x) {
                while (true) {
                    if (multi[x]) return -2; // shouldn't happen in this branch
                    int rr = x / W, cc = x % W;
                    int nxt = -1;
                    for (int t = 0; t < 4; ++t) {
                        int r2 = rr + dr[t], c2 = cc + dc[t];
                        if (r2 < 0 || r2 >= H || c2 < 0 || c2 >= W) continue;
                        int y = r2 * W + c2;
                        if (h[y] < h[x]) {
                            nxt = y;
                            break;
                        }
                    }
                    if (nxt == -1) return x; // sink
                    x = nxt;
                }
            };

            for (int k = 0; k < 4; ++k) {
                int nr = r + dr[k], nc = c + dc[k];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                int to = nr * W + nc;
                if (h[to] < h[v]) {
                    int s = getSink(to);
                    if (sinkRep == -1) sinkRep = s;
                    else if (sinkRep != s) {
                        different = true;
                        break;
                    }
                }
            }
            multi[v] = different ? 1 : 0;
        } else {
            multi[v] = 1;
        }
    }

    long long ans = 0;
    for (int i = 0; i < N; ++i) ans += multi[i];
    cout << ans << '\n';
    return 0;
}
